let backup_icon;let backup_name;function setCloak(name,icon){var tabicon=localStorage.getItem("obsidian.tabicon")||getCookie("tabicon");if(tabicon||icon){var link=document.querySelector("link[rel~='icon']");if(link){if(link.href!=icon){backup_icon=link}while(document.querySelector("link[rel~='icon']")){document.querySelector("link[rel~='icon']").remove()}}var link=document.querySelector("link[rel~='shortcut icon']");if(link){if(link.href!=icon){backup_icon=link}while(document.querySelector("link[rel~='shortcut icon']")){document.querySelector("link[rel~='shortcut icon']").remove()}}link=document.createElement("link");link.rel="icon";document.head.appendChild(link);link.href=tabicon;if(name){link.href=icon}}var tabname=localStorage.getItem("obsidian.tabname")||getCookie("tabname");backup_name=document.title;if(tabname){document.title=tabname}if(name){document.title=name}panicMode()}function getCookie(cname){let name=cname+"=";let decodedCookie=decodeURIComponent(document.cookie);let ca=decodedCookie.split(";");for(let i=0;i<ca.length;i+=1){let c=ca[i];while(c.charAt(0)==" "){c=c.substring(1)}if(c.indexOf(name)==0){return c.substring(name.length,c.length)}}return ""}function panicMode(){panicurl=getCookie("panicurl");if(panicurl==""){panicurl="https://google.com"}}document.addEventListener("DOMContentLoaded",()=>{setCloak();let plausible=document.createElement("script");plausible.setAttribute("event-domain",location.host);plausible.setAttribute("defer","");plausible.setAttribute("src","/js/analytics.js");plausible.setAttribute("data-domain","obsidiangame.github.io");document.head.appendChild(plausible)},false);if(location.pathname.substring(1).includes("semag")&&localStorage.getItem("obsidian.blockClose")=="true"){window.onbeforeunload=function(){return ""}}addEventListener("visibilitychange",(e)=>{if(localStorage.getItem("obsidian.tabDisguise")=="true"){if(document.visibilityState==="hidden"){setCloak("Google","https://www.google.com/favicon.ico")}else{if(!backup_icon){icon=document.createElement("link");icon.rel="icon";var link=document.querySelector("link[rel~='icon']");if(link){backup_icon=link;while(document.querySelector("link[rel~='icon']")){document.querySelector("link[rel~='icon']").remove()}}var link=document.querySelector("link[rel~='shortcut icon']");if(link){backup_icon=link;while(document.querySelector("link[rel~='shortcut icon']")){document.querySelector("link[rel~='shortcut icon']").remove()}}document.head.appendChild(icon);icon.href=location.origin+"/favicon.ico"}else{document.head.appendChild(backup_icon)}document.title=backup_name}}});var polyfillScript=document.createElement("script");polyfillScript.src="https://cdnjs.cloudflare.com/polyfill/v3/polyfill.min.js?version=4.8.0";document.head.appendChild(polyfillScript);function fps(){var script=document.createElement("script");script.onload=function(){var stats=new Stats();document.body.appendChild(stats.dom);requestAnimationFrame(function loop(){stats.update();requestAnimationFrame(loop)});localStorage.setItem("fps",true)};script.src="https://cdn.jsdelivr.net/gh/mrdoob/stats.js@master/build/stats.min.js";document.head.appendChild(script)}if(localStorage.getItem("fps")){fps()}